Projection.decl_schedule:
def decl_schedule():
    """The declared rates of the policy's rate scenario, by from_year."""
    return data.decl_rate_table().loc[rate_scenario()]

Projection.lapse_in_payment:
def lapse_in_payment():
    """The in-payment lapse rate of the policy's lapse basis."""
    return float(data.lapse_table().loc[(lapse_basis(), Segment.in_payment, 0), "lapse_rate"])

Projection.lapse_paid_up:
def lapse_paid_up():
    """The paid-up lapse rate of the policy's lapse basis."""
    return float(data.lapse_table().loc[(lapse_basis(), Segment.paid_up, 0), "lapse_rate"])

Projection.lapse_paying_schedule:
def lapse_paying_schedule():
    """The premium-paying lapse rates of the policy's lapse basis, by from_year."""
    return data.lapse_table().loc[(lapse_basis(), Segment.premium_paying)]
